<template><el-container><el-header><el-button @click="router.push('/health-home')">返回首页</el-button><h3>健康知识</h3></el-header><el-main><el-card v-for="a in articles" :key="a.id"><h2>{{a.title}}</h2><p>{{a.content}}</p><video v-if="a.media_type==='video'" :src="a.media_url" controls preload="metadata" style="max-width:100%"/></el-card></el-main></el-container></template><script setup>import{ref,onMounted}from'vue';import{useRouter}from'vue-router';import{call}from'@/api/health';const router=useRouter(),articles=ref([]);onMounted(async()=>articles.value=(await call('chat/knowledge')).data)</script><style scoped>.el-header{display:flex;align-items:center;gap:24px}.el-main{background:#f1f7f6;padding:32px 8vw;min-height:90vh}.el-card{margin-bottom:24px}p{line-height:1.9}</style>
